import numpy as np
import scipy.special as special

# Helper: record one ufunc call outcome
# We will attempt to use NEP50's multi-arg public ufunc mapping if available.

def get_multi_arg_ufuncs():
    # SciPy test suite uses this; try internal import first.
    for modname in [
        'scipy.special.tests.test_ufunc_signatures',
    ]:
        try:
            mod = __import__(modname, fromlist=['_multi_arg_public_ufuncs'])
            return getattr(mod, '_multi_arg_public_ufuncs')
        except Exception:
            pass
    # Fallback: try to locate candidates by scanning special module for ufuncs
    # whose name is known to be in NEP50 coverage.
    fallback = {}
    known = [
        'modstruve', 'struvel', 'hyp1f1', 'hyp2f1', 'hyperu',
        'i0', 'i1', 'j0', 'j1',
        'wofz' # might not be NEP50 multi-arg
    ]
    for name in dir(special):
        if name in known:
            obj = getattr(special, name)
            if isinstance(obj, np.ufunc):
                fallback[name] = obj
    return fallback

multi = get_multi_arg_ufuncs()

# Select a small, stable subset from the mapping/dict/structure.
# The test module typically stores descriptors with signature/typecodes.
# We introspect available info and then call a representative signature.

candidates = []

# multi may be list of tuples/dicts; normalize best-effort.
if isinstance(multi, dict):
    candidates = list(multi.items())
else:
    try:
        candidates = list(multi)
    except Exception:
        candidates = []

# We'll gather actual ufunc objects + (optional) signature info.
selected = []
for item in candidates:
    if isinstance(item, tuple) and len(item) >= 1:
        # could be (ufunc, ...) or (name, ufunc)
        u = None
        name = None
        if hasattr(item[0], 'nin') and isinstance(item[0], np.ufunc):
            u = item[0]
            name = getattr(u, '__name__', 'ufunc')
        elif len(item) >= 2 and isinstance(item[1], np.ufunc):
            u = item[1]
            name = str(item[0])
        if u is not None and hasattr(u, '__name__'):
            selected.append((name, u))
    elif isinstance(item, np.ufunc):
        selected.append((getattr(item, '__name__','ufunc'), item))

# Further reduce to known NEP50 multi-arg functions likely to show dtype behavior.
preferred_names = {'modstruve','struvel','hyp1f1','hyp2f1','hyperu','ellipf','ellipk','ellipkm1','ellipj'}
selected = [s for s in selected if s[0] in preferred_names]
if not selected:
    # If mapping structure differs, explicitly add known ufuncs when present.
    for name in ['modstruve','hyp1f1','hyp2f1','hyperu','struvel']:
        if hasattr(special, name):
            u = getattr(special, name)
            if isinstance(u, np.ufunc):
                selected.append((name, u))

# Keep at most 4 for speed.
selected = selected[:4]

# Record helper

def isnan_array(x):
    try:
        return bool(np.isnan(x))
    except Exception:
        try:
            # complex: isnan checks elementwise; treat scalar complex
            return bool(np.isnan(np.real(x)) or np.isnan(np.imag(x)))
        except Exception:
            return None


def make_nan_and_args(ufunc, dtype):
    # Create dtype-appropriate nan scalar and placeholders.
    nan = dtype(type(np.nan)) if np.dtype(dtype).kind in ['f'] else dtype(np.nan+0j)
    # Build generic arguments based on ufunc.nin with heuristic: fill with 1.5 of dtype.
    nin = ufunc.nin
    args = []
    for i in range(nin):
        # Put distinctive non-NaN defaults
        if np.dtype(dtype).kind == 'c':
            args.append(dtype(1.25 + 0.0j))
        else:
            args.append(dtype(1.25))
    # Replace one argument with python float nan to mimic test behavior.
    idx = 0 if nin > 0 else None
    if idx is not None:
        args[idx] = float('nan')
    return args

# Run calls and record.
# Use both float64 and float32 to trigger dtype promotion differences.
for name, u in selected:
    # attempt two dtypes
    for dtype in [np.float32, np.float64]:
        args = make_nan_and_args(u, dtype)
        try:
            res = u(*args)
            # Some ufuncs may return tuples; normalize
            if isinstance(res, tuple):
                out = res[0]
            else:
                out = res
            # dtype capture
            odt = getattr(out, 'dtype', None)
            # NaN capture
            nanflag = isnan_array(out)
            # record
            probe(f"{name}|dtype_in={np.dtype(dtype).name}|out_dtype={odt}", nanflag)
            probe(f"{name}|dtype_in={np.dtype(dtype).name}|out_value_dtype", 0 if odt is None else str(odt))
        except Exception as e:
            probe(f"{name}|dtype_in={np.dtype(dtype).name}|exception", 1)

# Ensure at least one observation exists even if selection empty.
if not selected:
    probe('nep50_selection_empty', 0)

